import{_ as e,o as a,c as l,Q as i}from"./chunks/framework.8829fefa.js";const t="/static/mobile-install-plugin.b2058e9c.png",b=JSON.parse('{"title":"如何安装插件","description":"","frontmatter":{"outline":"deep","prev":"安卓版-如何安装应用","next":"桌面版-如何安装应用"},"headers":[],"relativePath":"usage/mobile/install-plugin.md","filePath":"usage/mobile/install-plugin.md","lastUpdated":1743988102000}'),s={name:"usage/mobile/install-plugin.md"},o=i('<h1 id="如何安装插件" tabindex="-1">如何安装插件 <a class="header-anchor" href="#如何安装插件" aria-label="Permalink to &quot;如何安装插件&quot;">​</a></h1><p>安卓版插件具体操作如下，你可以选择任意一种方式安装插件：</p><p><img src="'+t+'" alt=""></p><h2 id="通过网络安装" tabindex="-1">通过网络安装 <a class="header-anchor" href="#通过网络安装" aria-label="Permalink to &quot;通过网络安装&quot;">​</a></h2><ol><li><p>点击左上角按钮</p></li><li><p>点击【插件设置】</p></li><li><p>点击右下角加号</p></li><li><p>点击【从网络安装插件】</p></li><li><p>输入插件 URL 即可（插件链接以 .json 或 .js 结尾）</p></li></ol><div class="info custom-block"><p class="custom-block-title">💡 示例插件</p><p>如果要使用示例插件，输入下面链接： <a href="https://gitee.com/fish-job/MusicFreePlugins/raw/master/plugins.json" target="_blank" rel="noreferrer">https://gitee.com/fish-job/MusicFreePlugins/raw/master/plugins.json</a></p></div><h2 id="通过本地文件安装" tabindex="-1">通过本地文件安装 <a class="header-anchor" href="#通过本地文件安装" aria-label="Permalink to &quot;通过本地文件安装&quot;">​</a></h2><ol><li><p>点击左上角按钮</p></li><li><p>点击【插件设置】</p></li><li><p>点击右下角加号</p></li><li><p>点击【从本地安装插件】</p></li><li><p>在选择本地的插件即可（本地的插件是一个 json 或 js 文件）</p></li></ol><h2 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h2><p>订阅地址和从网络安装插件的地址完全相同。</p><p>当添加订阅地址后，可以点击【更新订阅】更新订阅源提供的所有插件。</p>',11),p=[o];function n(r,c,h,d,u,_){return a(),l("div",null,p)}const g=e(s,[["render",n]]);export{b as __pageData,g as default};
